  "Track student performance, highlight weak areas, and get customized study paths": "\u091B\u093E\u0924\u094D\u0930\u094B\u0902 \u0915\u0940 \u092A\u094D\u0930\u0917\u0924\u093F \u091F\u094D\u0930\u0948\u0915 \u0915\u0930\u0947\u0902, \u0915\u092E\u091C\u093C\u094B\u0930 \u0915\u094D\u0937\u0947\u0924\u094D\u0930\u094B\u0902 \u0915\u094B \u0909\u091C\u093E\u0917\u0930 \u0915\u0930\u0947\u0902 \u0914\u0930 \u0935\u0948\u092F\u0915\u094D\u0924\u093F\u0915\u0943\u0924 \u0905\u0927\u094D\u092F\u092F\u0928 \u092A\u0925 \u092A\u093E\u090F\u0902",
  "Overall Accuracy": "\u0938\u092E\u0917\u094D\u0930 \u0936\u0941\u0926\u094D\u0927\u0924\u093E",
  "Declensions": "\u0930\u0942\u092A-\u0935\u093F\u092D\u0915\u094D\u0924\u093F\u092F\u093E\u0901",
  "Sandhi Rules": "\u0938\u0902\u0927\u093F \u0928\u093F\u092F\u092E",
  "Verb Conjugation": "\u0915\u094D\u0930\u093F\u092F\u093E \u0930\u0942\u092A",
  "Study Time Today": "\u0906\u091C \u0915\u093E \u0905\u0927\u094D\u092F\u092F\u0928 \u0938\u092E\u092F",
  "Weak Areas \u2014 Recommendations": "\u0915\u092E\u091C\u093C\u094B\u0930 \u0915\u094D\u0937\u0947\u0924\u094D\u0930 \u2014 \u0905\u0928\u0941\u0936\u0902\u0938\u093E\u090F\u0901",
  "Practice present tense parasmaipada forms": "\u0935\u0930\u094D\u0924\u092E\u093E\u0928 \u092A\u0930\u0938\u094D\u092E\u0948\u092A\u0926 \u0930\u0942\u092A\u094B\u0902 \u0915\u093E \u0905\u092D\u094D\u092F\u093E\u0938 \u0915\u0930\u0947\u0902",
  "Focus on gu\u1E47a and v\u1E5Bddhi sandhi": "\u0917\u0941\u0923 \u0914\u0930 \u0935\u0943\u0926\u094D\u0927\u093F \u0938\u0902\u0927\u093F \u092A\u0930 \u0927\u094D\u092F\u093E\u0928 \u0926\u0947\u0902",
  "Maintain current practice schedule": "\u0935\u0930\u094D\u0924\u092E\u093E\u0928 \u0905\u092D\u094D\u092F\u093E\u0938 \u0926\u093F\u0928\u091A\u0930\u094D\u092F\u093E \u092C\u0928\u093E\u090F \u0930\u0916\u0947\u0902",
  "Recommended Study Path": "\u0905\u0928\u0941\u0936\u0902\u0938\u093F\u0924 \u0905\u0927\u094D\u092F\u092F\u0928 \u092A\u0925",
  "Week 1 \u2014 Sandhi Deep Dive": "\u0938\u092A\u094D\u0924\u093E\u0939 1 \u2014 \u0938\u0902\u0927\u093F \u0917\u0939\u0928 \u0905\u0927\u094D\u092F\u092F\u0928",
  "Gu\u1E47a, V\u1E5Bddhi, Ya\u1E47 rules with 100+ practice examples": "\u0917\u0941\u0923, \u0935\u0943\u0926\u094D\u0927\u093F, \u092F\u0923 \u0928\u093F\u092F\u092E 100+ \u0905\u092D\u094D\u092F\u093E\u0938 \u0909\u0926\u093E\u0939\u0930\u0923\u094B\u0902 \u0938\u0939\u093F\u0924",
  "Week 2 \u2014 Verb Conjugation": "\u0938\u092A\u094D\u0924\u093E\u0939 2 \u2014 \u0915\u094D\u0930\u093F\u092F\u093E \u0930\u0942\u092A",
  "Present, imperfect, and optative moods": "\u0935\u0930\u094D\u0924\u092E\u093E\u0928, \u0905\u092A\u0942\u0930\u094D\u0923 \u0914\u0930 \u0907\u091A\u094D\u091B\u093E\u0930\u094D\u0925 \u0935\u0943\u0924\u094D\u0924\u093F\u092F\u093E\u0901",
  "Week 3 \u2014 Compound Analysis": "\u0938\u092A\u094D\u0924\u093E\u0939 3 \u2014 \u0938\u092E\u093E\u0938 \u0935\u093F\u0936\u094D\u0932\u0947\u0937\u0923",
  "Tatpuru\u1E63a, Bahuvr\u012Bhi, Avyay\u012Bbh\u0101va compounds": "\u0924\u0924\u094D\u092A\u0941\u0930\u0941\u0937, \u092C\u0939\u0941\u0935\u094D\u0930\u0940\u0939\u093F, \u0905\u0935\u094D\u092F\u092F\u0940\u092D\u093E\u0935 \u0938\u092E\u093E\u0938",
  "Recommended Study Schedule": "\u0905\u0928\u0941\u0936\u0902\u0938\u093F\u0924 \u0905\u0927\u094D\u092F\u092F\u0928 \u0905\u0928\u0941\u0938\u0942\u091A\u0940",
  // Viewer3DPage
  "Interactive Three.js 3D models of palm-leaf manuscripts with digitized text overlays": "\u0905\u0902\u0915\u0940\u092F \u092A\u093E\u0920 \u0913\u0935\u0930\u0932\u0947 \u0938\u0939\u093F\u0924 \u0924\u093E\u0921\u093C\u092A\u0924\u094D\u0930 \u092A\u093E\u0902\u0921\u0941\u0932\u093F\u092A\u093F\u092F\u094B\u0902 \u0915\u0947 \u0907\u0902\u091F\u0930\u0948\u0915\u094D\u091F\u093F\u0935 \u0925\u094D\u0930\u0940.\u091C\u0947\u093C\u0938 3D \u092E\u0949\u0921\u0932",
  "Drag to rotate \xB7 Scroll to zoom \xB7 Auto-rotating": "\u0918\u0941\u092E\u093E\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0916\u0940\u0902\u091A\u0947\u0902 \xB7 \u091C\u093C\u0942\u092E \u0915\u0930\u0928\u0947 \u0915\u0947 \u0932\u093F\u090F \u0938\u094D\u0915\u094D\u0930\u0949\u0932 \u0915\u0930\u0947\u0902 \xB7 \u0938\u094D\u0935\u0924\u0903 \u0918\u0942\u0930\u094D\u0923\u0928",
  "Available Manuscripts": "\u0909\u092A\u0932\u092C\u094D\u0927 \u092A\u093E\u0902\u0921\u0941\u0932\u093F\u092A\u093F\u092F\u093E\u0901",
  "Viewing": "\u0926\u0947\u0916 \u0930\u0939\u0947 \u0939\u0948\u0902",
  // GrammarMapsPage
  "3D branching diagrams of P\u0101\u1E47ini's grammar and visual network maps of Indian philosophy": "\u092A\u093E\u0923\u093F\u0928\u093F \u0915\u0947 \u0935\u094D\u092F\u093E\u0915\u0930\u0923 \u0915\u0947 3D \u0936\u093E\u0916\u093E \u0906\u0930\u0947\u0916 \u0924\u0925\u093E \u092D\u093E\u0930\u0924\u0940\u092F \u0926\u0930\u094D\u0936\u0928 \u0915\u0947 \u0926\u0943\u0936\u094D\u092F \u0928\u0947\u091F\u0935\u0930\u094D\u0915 \u092E\u093E\u0928\u091A\u093F\u0924\u094D\u0930",
  "P\u0101\u1E47ini Grammar Rules": "\u092A\u093E\u0923\u093F\u0928\u093F \u0935\u094D\u092F\u093E\u0915\u0930\u0923 \u0928\u093F\u092F\u092E",
  "Philosophy Networks": "\u0926\u0930\u094D\u0936\u0928 \u0928\u0947\u091F\u0935\u0930\u094D\u0915",
  "3D GRAMMAR GRAPH": "3D \u0935\u094D\u092F\u093E\u0915\u0930\u0923 \u0917\u094D\u0930\u093E\u092B",
