  "attempts": "\u092A\u094D\u0930\u092F\u093E\u0938",
  "avg": "\u0914\u0938\u0924",
  "e.g. \u0930\u093E\u092E\u0903 \u0935\u0928\u0947 \u0935\u0938\u0924\u093F \u2014 or type in IAST: r\u0101ma\u1E25 vane vasati": "\u091C\u0948\u0938\u0947 \u0930\u093E\u092E\u0903 \u0935\u0928\u0947 \u0935\u0938\u0924\u093F \u2014 \u092F\u093E IAST \u092E\u0947\u0902 \u091F\u093E\u0907\u092A \u0915\u0930\u0947\u0902: r\u0101ma\u1E25 vane vasati",
  "ga\u1E47a": "\u0917\u0923",
  "lookup": "\u0916\u094B\u091C\u0947\u0902",
  "mistakes.": "\u0917\u0932\u0924\u093F\u092F\u093E\u0901\u0964",
